char *resize_array(char *old, size_t old_len, size_t add_len) {
    if (add_len > SIZE_MAX - old_len)
        return NULL;
    size_t new_len = old_len + add_len;
    char *new_buf = realloc(old, new_len);
    return new_buf;
}

